package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.Rect;
import android.view.inspector.WindowInspector;
import android.widget.TextView;
import android.view.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Real named database/WAVs and native UI. Review sessions are injected fakes, never MediaPlayer. */
public class FavoriteSoundsFlowTest {
    @org.junit.Rule public final SoundBrowseTestScope browseScope=new SoundBrowseTestScope();
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private String step="fixture admission";
    private FavoriteSoundsActivity focused(FavoriteSoundsActivity previous){long until=SystemClock.elapsedRealtime()+5000;FavoriteSoundsActivity[] found={null};while(found[0]==null){i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof FavoriteSoundsActivity&&a!=previous&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=(FavoriteSoundsActivity)a;});assertTrue("Focused destination frame",found[0]!=null||SystemClock.elapsedRealtime()<until);if(found[0]==null)SystemClock.sleep(30);}return found[0];}
    private void destroyed(Activity activity){long until=SystemClock.elapsedRealtime()+5000;boolean[] ended={false};while(!ended[0]){i.runOnMainSync(()->ended[0]=activity.isDestroyed());assertTrue("Owned screen destroyed",ended[0]||SystemClock.elapsedRealtime()<until);if(!ended[0])SystemClock.sleep(30);}}
    private void object(BySelector selector){assertTrue(step+": "+selector,device.wait(Until.hasObject(selector),5000));}
    private View focusedWindow(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0){assertNull("One focused application window",found);found=root;}return found;}
    private View find(View root,String label,boolean description){if(description?label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()):root instanceof TextView&&label.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),label,description);if(found!=null)return found;}return null;}
    private void await(java.util.function.BooleanSupplier predicate){assertTrue(step,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return predicate.getAsBoolean();}},5000));}
    private View ownedWindow(String heading,boolean dialog){View[] owner={null};await(()->{i.runOnMainSync(()->{View root=focusedWindow();if(root==null||find(root,heading,false)==null)return;boolean page=false;for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof FavoriteSoundsActivity||a instanceof SoundEventsActivity)page|=a.getWindow().getDecorView()==root;if(page!=dialog)owner[0]=root;});return owner[0]!=null;});return owner[0];}
    private void input(String label,boolean description,View required)throws Exception{
        step="single input "+label;View[] owner={null};
        await(()->{boolean[] ready={false};i.runOnMainSync(()->{View root=focusedWindow();if(root==null||required!=null&&root!=required)return;View target=find(root,label,description);if(target==null)return;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();if(!target.isClickable()||!target.isEnabled()||!target.isShown())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();ready[0]=target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();if(ready[0])owner[0]=root;});return ready[0];});
        CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Input frame belongs to current owned window",owner[0],focusedWindow());owner[0].getViewTreeObserver().registerFrameCommitCallback(frame::countDown);owner[0].invalidate();});assertTrue(step+": frame committed",frame.await(5,TimeUnit.SECONDS));
        Rect bounds=new Rect();i.runOnMainSync(()->{assertSame("Input still belongs to focused owned window",owner[0],focusedWindow());View target=find(owner[0],label,description);assertNotNull(step,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertSame("Target belongs to exact owned decor",owner[0],target.getRootView());assertTrue("Actionable target",target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals("Complete input height",target.getHeight(),visible.height());assertEquals("Complete input width",target.getWidth(),visible.width());assertTrue("48dp input height",visible.height()>=Design.dp(c,48));assertTrue("48dp input width",visible.width()>=Design.dp(c,48));int[] screen=new int[2];target.getLocationOnScreen(screen);bounds.set(screen[0],screen[1],screen[0]+target.getWidth(),screen[1]+target.getHeight());});
        // One input only. No retained accessibility node, blind action retry or content-change acknowledgment.
        assertTrue(step+": delivered once",device.click(bounds.centerX(),bounds.centerY()));
    }
    private void click(String label,boolean description)throws Exception{input(label,description,null);}
    private void choose(String heading,String label)throws Exception{step="owned "+heading+" choice "+label;View owner=ownedWindow(heading,true);input(label,false,owner);await(()->!owner.isAttachedToWindow());}
    private void capture(File folder,String name)throws Exception{step="capture "+name;FavoriteSoundsActivity a=focused(null);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View view=a.getWindow().getDecorView();view.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);view.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();assertTrue(device.takeScreenshot(new File(folder,name+".png")));}
    private ClipSeekView shownSeek(View root){if(root instanceof ClipSeekView&&root.isShown())return (ClipSeekView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int n=0;n<group.getChildCount();n++){ClipSeekView value=shownSeek(group.getChildAt(n));if(value!=null)return value;}}return null;}
    private FavoriteSoundsActivity reopen(FavoriteSoundsActivity previous){i.runOnMainSync(previous::finish);destroyed(previous);c.startActivity(new Intent(c,FavoriteSoundsActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic favorites · fake playback").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return focused(previous);}
    @Test public void globalAlbumFiltersPlaysPersistsAndHandlesSharedDeletedMissingAndUnavailableData()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));Map<String,?> prefs=Prefs.of(c).getAll();Records.Factory prior=Records.factory;ClipPlayback.Provider priorPlayback=ClipPlayback.provider;List<Activity> owned=new CopyOnWriteArrayList<>();List<SoundLibraryUiTest.FakePort> ports=new CopyOnWriteArrayList<>();AtomicBoolean fail=new AtomicBoolean();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){if(a instanceof FavoriteSoundsActivity||a instanceof SoundEventsActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);FavoriteSoundsFixture fixture=new FavoriteSoundsFixture();boolean drained=false;
        try{
            fixture.standard();String recent="event:"+fixture.recentEvent.getLong("id"),old="event:"+fixture.oldEvent.getLong("id");i.runOnMainSync(()->{Records.factory=context->{if(fail.get())throw new IllegalStateException("Synthetic database unavailable");return new Store(context,fixture.database);};ClipPlayback.provider=(context,source)->{SoundLibraryUiTest.FakePort port=new SoundLibraryUiTest.FakePort();ports.add(port);return port;};c.startActivity(new Intent(c,SoundEventsActivity.class).putExtra("record",1L).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic favorites · fake playback").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});
            step="await completed real night load before options";
            object(By.desc("All (1)"));
            View source=ownedWindow("Sound events",false);
            input("Sound event options",true,source);
            choose("Sound events","Favorite sounds");
            FavoriteSoundsActivity first=focused(null);object(By.desc("All (4)"));assertTrue(device.hasObject(By.desc("Unfavorite "+recent)));assertTrue(ports.get(1).sessions.isEmpty());capture(folder,"favorites-all");
            String clipKey="clip:"+fixture.recentClip.getLong("id");click("Play "+clipKey,true);object(By.desc("Pause "+clipKey));SoundLibraryUiTest.FakeSession whole=ports.get(1).sessions.get(0);assertEquals(0,whole.target.fromMs);assertEquals(10000,whole.target.durationMs);click("Play "+recent,true);object(By.desc("Pause "+recent));assertTrue(whole.closes>0);SoundLibraryUiTest.FakeSession session=ports.get(1).sessions.get(1);assertEquals(1000,session.target.fromMs);assertEquals(1950,session.target.durationMs);i.runOnMainSync(()->{ClipSeekView seek=shownSeek(first.getWindow().getDecorView());assertNotNull(seek);Bundle values=new Bundle();values.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,900);assertTrue(seek.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),values));});assertEquals(900,session.seek);capture(folder,"favorites-playback");
            i.runOnMainSync(first::recreate);FavoriteSoundsActivity recreated=focused(first);destroyed(first);object(By.desc("Play "+recent));assertTrue(ports.get(2).sessions.isEmpty());capture(folder,"favorites-recreated");
            click("Filter favorite dates",true);choose("Favorite dates","Past 7 days");assertTrue(device.wait(Until.gone(By.desc("Past 7 days")),3000));object(By.text("Past 7 days · 3 favorites"));object(By.desc("Speech (0)"));capture(folder,"favorites-week");click("Speech (0)",true);object(By.text("No favorites in this view"));capture(folder,"favorites-filter-empty");click("Show all favorites",false);click("Speech (1)",true);click("Play "+old,true);object(By.desc("Pause "+old));SoundLibraryUiTest.FakeSession speech=ports.get(2).sessions.get(0);assertEquals(2000,speech.target.fromMs);capture(folder,"favorites-speech");i.runOnMainSync(()->speech.events.failed("This recording could not play."));object(By.text("This recording could not play."));assertTrue(fixture.files.get(1).exists());capture(folder,"favorites-playback-error");
            click("All (4)",true);click("Unfavorite "+recent,true);object(By.desc("All (3)"));assertFalse(device.hasObject(By.desc("Unfavorite "+recent)));assertEquals(0,fixture.store.rows("SELECT favorite FROM sound_events WHERE id=?",""+fixture.recentEvent.getLong("id")).get(0).getInt("favorite"));assertEquals(1,fixture.store.rows("SELECT favorite FROM clips WHERE id=?",""+fixture.recentClip.getLong("id")).get(0).getInt("favorite"));assertTrue(fixture.files.get(0).exists());capture(folder,"favorites-unstarred");FavoriteSoundsActivity reopened=reopen(recreated);object(By.desc("All (3)"));assertFalse(device.hasObject(By.desc("Unfavorite "+recent)));capture(folder,"favorites-reopened");
            org.json.JSONObject oldClip=fixture.store.rows("SELECT * FROM clips WHERE session=2").get(0);SoundClips.delete(c,fixture.store,oldClip);reopened=reopen(reopened);click("Speech (1)",true);object(By.text("Audio not recorded"));assertFalse(device.hasObject(By.desc("Play "+old)));assertEquals(1,fixture.store.rows("SELECT favorite FROM sound_events WHERE id=?",""+fixture.oldEvent.getLong("id")).get(0).getInt("favorite"));capture(folder,"favorites-deleted-audio");assertTrue(fixture.files.get(0).delete());reopened=reopen(reopened);click("All (3)",true);object(By.text("Recording unavailable"));assertFalse(device.hasObject(By.desc("Play clip:"+fixture.recentClip.getLong("id"))));capture(folder,"favorites-missing-audio");
            SoundClips.favorite(fixture.store,fixture.recentClip,false);SoundClips.favoriteEvent(fixture.store,fixture.oldEvent,false);SoundClips.favoriteEvent(fixture.store,fixture.analysisEvent,false);reopened=reopen(reopened);object(By.text("No favorite sounds yet"));assertEquals(3,fixture.store.rows("SELECT id FROM sound_events").size());assertEquals(1,fixture.store.rows("SELECT id FROM clips").size());capture(folder,"favorites-empty");fail.set(true);reopened=reopen(reopened);object(By.text("Favorite sounds could not be loaded."));capture(folder,"favorites-error");fail.set(false);click("Try again",false);object(By.text("No favorite sounds yet"));capture(folder,"favorites-retry");assertEquals(prefs,Prefs.of(c).getAll());
        }catch(Throwable failure){try{try(PrintWriter note=new PrintWriter(new File(folder,"favorites-failure.txt"),"UTF-8")){note.println(step);failure.printStackTrace(note);}device.takeScreenshot(new File(folder,"favorites-failure.png"));device.dumpWindowHierarchy(new File(folder,"favorites-failure.xml"));}catch(Throwable diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});for(Activity a:owned)destroyed(a);for(Activity a:owned)assertTrue(a instanceof FavoriteSoundsActivity?((FavoriteSoundsActivity)a).awaitReaders(5000):((SoundEventsActivity)a).awaitReaders(5000));drained=true;}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=prior;ClipPlayback.provider=priorPlayback;});if(drained)fixture.close();assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}}
    }
}
